import styled from '@emotion/styled';
import { Grid } from 'components/UI';

interface StyledGridContainerProps {
  $isExportPage?: boolean;
  $isResponsivePage?: boolean;
}

export const StyledGridContainer = styled(Grid.Container, {
  shouldForwardProp: (propName) =>
    !['$isExportPage', '$isResponsivePage'].includes(propName),
})<StyledGridContainerProps>(({ $isExportPage, $isResponsivePage }) => ({
  width: '1328px !important',
  position: 'relative',
  left: 'max(96px, 50% - 664px)',
  paddingBottom: '2rem',
  margin: '0 !important',
  ...($isExportPage && {
    width: '1668px !important',
    position: 'relative',
    left: 'max(96px, 50% - 834px)',
  }),
  ...($isResponsivePage && {
    width: '1096px !important',
    position: 'relative',
    left: 'max(80px, calc(40px + 50% - 548px))',

    '@media (min-width: 1440px)': {
      width: '1256px !important',
      left: 'max(80px, calc(40px + 50% - 628px))',
    },
    '@media (min-width: 1920px)': {
      width: '1440px !important',
      left: 'max(80px, calc(40px + 50% - 720px))',
    },
  }),
}));

export const StyledHomeContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '1rem',
  padding: 0,
  width: '100%',
});

export const StyledHomeHeaderContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
});

export const StyledSectionContent = styled.div({
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'center',
  alignItems: 'center',
  gap: '1rem',
  padding: '0 24px 24px 24px',
});

export const StyledGridItem = styled(Grid.Item)({
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
  padding: '0 !important',
});

interface StyledExpandableContainerProps {
  $isExportPage?: boolean;
}

export const StyledExpandableContainer = styled('div', {
  shouldForwardProp: (propName) => propName !== '$isExportPage',
})<StyledExpandableContainerProps>(({ $isExportPage }) => ({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  maxWidth: '1280px',
  minHeight: '196px',
  justifyContent: 'center',
  paddingBottom: '16px',
  ...($isExportPage && {
    maxWidth: '1668px',
    alignItems: 'start',
  }),
}));

export const StyledGlobalDataBanner = styled.div({
  marginBottom: '1.5rem',
  width: '100%',
});
